from pathlib import Path
import json,shutil,hashlib,html
R=Path(__file__).resolve().parents[1];src=R/'reports/same-prompt';out=R/'docs/samples/same-prompt';out.mkdir(parents=True,exist_ok=True)
metrics=json.loads((src/'metrics.json').read_text());cards=[];rows=[]
for seed in [10,40,47]:
 name='seed-'+str(seed);d=json.loads((src/(name+'.json')).read_text());m=next(v for v in metrics['results'] if v['mode']==name)
 for suffix in ['.mp4','-7.png','-prompt.txt']:shutil.copyfile(src/(name+suffix),out/(name+suffix))
 digest=hashlib.sha256((out/(name+'.mp4')).read_bytes()).hexdigest();events=d['world']['events'];times=[round(e['time'],3) for e in events if e['type']=='escape'];rows.append({'seed':seed,'prompt_sha256':d['promptHash'],'settings':d['settings'],'video':name+'.mp4','video_sha256':digest,'escape_times_seconds':times,'metrics':m})
 cards.append(f'<article><h2>Seed {seed}</h2><video controls playsinline preload="metadata" muted poster="{name}-7.png" src="{name}.mp4?v={digest[:12]}"></video><a download href="{name}.mp4">MP4を保存</a><button type="button" data-share="{name}.mp4">共有 / ファイルに保存</button><p>突破時刻: {html.escape(str(times))} 秒<br>実測平均 {m["encoded_average_fps"]:.1f}fps / A/V残差 {m["audio_timeline_residual_seconds"]*1000:.1f}ms</p></article>')
prompt=d['prompt'];(out/'common-prompt.txt').write_bytes(prompt.encode());shutil.copyfile(R/'docs/experiment/reference.json',out/'reference.json');shutil.copyfile(R/'reports/SAME_PROMPT_ANALYSIS.md',out/'analysis.md');shutil.copyfile(src/'metrics.json',out/'metrics.json');(out/'manifest.json').write_text(json.dumps({'version':'same-prompt-1','prompt':prompt,'prompt_sha256':d['promptHash'],'seed_only_difference':True,'videos':rows,'iphone_safari':'UNTESTED','source_visual_analysis':'UNVERIFIED'},ensure_ascii=False,indent=2))
(out/'index.html').write_text('''<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>同一プロンプト × 3 seeds</title><style>body{background:#09111f;color:#edf5ff;font:16px system-ui;max-width:1200px;margin:24px auto;padding:0 16px}a{color:#8ce9ee}p{line-height:1.8}button,select{font:inherit;padding:12px;border-radius:8px;margin:4px;min-height:44px}article{background:#142035;border-radius:16px;padding:16px;min-width:0}video{width:100%;max-height:65vh;background:#050910}article a{display:inline-block;padding:12px}.scroll{overflow-x:auto}.three{display:grid;grid-template-columns:repeat(3,minmax(260px,1fr));gap:16px}pre{white-space:pre-wrap;overflow-wrap:anywhere;background:#142035;padding:16px}h1{font-size:30px}#status{min-height:2em}</style><a href="../../">アプリへ</a><h1>同じプロンプト。違う3つの軌道。</h1><p>720×1280・15秒・同一物理設定・同一描画と音声処理。変更した生成入力はシード10・40・47のみ。文章は固定レシピへ変換する方式で、生成AIモデルの推論ではありません。3本とも実録画したH.264/AACのMP4です。</p><button id="play">3本を先頭から再生</button><button id="pause">すべて停止</button><label>音声<select id="audio"><option value="0">Seed 10</option><option value="1">Seed 40</option><option value="2">Seed 47</option><option value="-1">無音</option></select></label><p id="status" role="status">スマートフォンでは横にスワイプして3本を比較できます。同時再生の厳密な同期は端末に依存します。</p><div class="scroll"><div class="three">'''+''.join(cards)+'''</div></div><h2>共通プロンプト（3本で完全一致）</h2><pre>'''+html.escape(prompt)+'''</pre><p>UTF-8 SHA-256: <code style="overflow-wrap:anywhere">'''+d['promptHash']+'''</code></p><a download href="common-prompt.txt">共通プロンプト原文</a> · <a href="manifest.json">設定・シード・動画ハッシュ</a> · <a href="metrics.json">実測QA</a><h2>参考動画との比較範囲</h2><p><a href="https://www.instagram.com/reel/DeUvaLwMp3o/">@music.bouncingball / Will the Ball Merge Into Final Form?</a> を参考候補に選定。二次情報では33.7M再生・1.7Mいいねですが、元投稿で未確認です。Instagramの取得制限により映像・音は直接視聴できず、リング構造も確認できていません。そのため高精度な再現・元作品より改善したという判定はできません。</p><p>今回の独自設計：連続衝突判定、球全体での隙間通過、抑えた光沢・発光、固定構図、イベント時刻に同期した自作音。これらは制作上の対策であり、元作品の欠点を示すものではありません。音色・質感の好みと視聴体験は再生して確認してください。</p><p>シードは録画前の数値シミュレーションで終盤まで展開がある3つを選定し、録画後は差し替えていません。録画開始待ちにより実ファイルは約15.1秒。可変フレーム間隔を保持し、重複フレームを挿入してFPSを増やしていません。音声同期は1ms音声・4.17ms映像照合刻みの推定です。全3本に同じ手順で実測ずれに応じた音声パケット時刻補正を適用し、映像フレームと音声内容は再圧縮せず保持します。補正前後の値は実測QAに記録します。</p><p>iPhone Safari実機の同時再生・音・保存・発熱は未検証。自動QAの合格だけで完全な品質を保証せず、大量生成は停止を継続します。</p><a href="analysis.md">分析・制約・合格基準</a> · <a href="reference.json">出典の検証状態</a><script type="module">const videos=[...document.querySelectorAll('video')],status=document.querySelector('#status'),audio=document.querySelector('#audio');function mix(){videos.forEach((v,i)=>v.muted=i!==Number(audio.value))}audio.onchange=mix;mix();document.querySelector('#play').onclick=async()=>{videos.forEach(v=>{v.pause();v.currentTime=0});const r=await Promise.allSettled(videos.map(v=>v.play()));status.textContent=r.some(v=>v.status==='rejected')?'同時再生を開始できない動画があります。個別の再生ボタンを使ってください。':'3本を再生中（端末により開始時刻の差が生じます）'};document.querySelector('#pause').onclick=()=>videos.forEach(v=>v.pause());document.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{try{const response=await fetch(b.dataset.share);if(!response.ok)throw Error('動画取得に失敗');const file=new File([await response.blob()],b.dataset.share,{type:'video/mp4'});if(navigator.canShare?.({files:[file]})){await navigator.share({files:[file],title:'Ring Escape'});status.textContent='共有シートで「ファイルに保存」を選択してください。'}else{status.textContent='共有に非対応です。「MP4を保存」からダウンロードしてください。'}}catch(e){status.textContent=e.name==='AbortError'?'共有をキャンセルしました。':e.message}});</script></html>''')
print('PASS published exactly3 controlled MP4s')
